import { ok, fail } from './result.js';
import { invoiceTotals } from './invoices.js';
import { nextCreditNoteNumber } from './numbering.js';

/**
 * Create a credit note for an issued invoice.
 * @param {{ status: string, number: string, customerId: string }} invoice
 * @param {{ amount: number, reason: string, date: string }} creditData
 * @param {string[]} existingNumbers - Array of existing invoice and credit note numbers
 * @returns {{ ok: true, value: { number: string, invoiceNumber: string, customerId: string, amount: number, reason: string, date: string } } | { ok: false, error: string }}
 */
export function createCreditNote(invoice, { amount, reason, date }, existingNumbers) {
  // Validate invoice status is 'issued', 'partially_paid', or 'paid'
  if (invoice.status !== 'issued' && invoice.status !== 'partially_paid' && invoice.status !== 'paid') {
    return fail('NOT_ISSUED');
  }

  // Validate amount is a positive integer
  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');

  // Get invoice total and check credit is not too high
  const totalsResult = invoiceTotals(invoice);
  if (!totalsResult.ok) return totalsResult;

  const invoiceTotal = totalsResult.value.total;
  if (amount > invoiceTotal) return fail('CREDIT_TOO_HIGH');

  // Generate the credit note number
  const number = nextCreditNoteNumber(existingNumbers, date);

  return ok({
    number,
    invoiceNumber: invoice.number,
    customerId: invoice.customerId,
    amount,
    reason,
    date,
  });
}

